<%
// ============================================================
// 渐变带 · 施法调度与战术决策面板 (正文AI专用)
// 包含：挂单代码裁决、精神负荷分级、固定/自由槽战术区别、过载判定、形态锚点
// 适配变更（随扩展 v1.8.3 / v1.8.4 的新回路结构）：
//   ① 回路新增「物理相态与表征」= 正文AI 叙事唯一形态锚点（法术AI 送审产出，开局预设亦有）
//   ② 过载率键名修正：旧写「过载率%」是幽灵键，引擎从未写入 → 过载率恒被读成 100%
//   ③ 走火判定改消费脚本预掷的「本轮走火」，与结算结果严格一致（旧版在面板内另摇一次骰）
// ============================================================

function fetchSnapshot() {
    try {
        if (typeof getvar === 'function') {
            for (var i = -1; i >= -6; i--) {
                var v = getvar('stat_data.渐变带', { scope: 'message', withMsg: { id: i } });
                if (v && v['主角']) return v;
            }
        }
    } catch (e) {}

    if (typeof variables !== 'undefined' && variables) {
        if (variables.stat_data && variables.stat_data['渐变带'] && variables.stat_data['渐变带']['主角']) {
            return variables.stat_data['渐变带'];
        }
        if (variables['渐变带'] && variables['渐变带']['主角']) {
            return variables['渐变带'];
        }
    }
    return null;
}

var ANCHOR_TABLE = [
    [100, '一记重拳'],
    [1000, '≈手枪弹击发力'],
    [10000, '≈步枪弹穿透力'],
    [100000, '≈轿车60码撞击'],
    [1000000, '≈1/4公斤TNT爆炸'],
    [10000000, '≈2.4公斤TNT爆炸'],
    [100000000, '≈24公斤TNT爆炸'],
    [1000000000, '≈半吨TNT爆炸'],
    [1e12, '≈战术核弹破坏'],
    [Infinity, '≈战略级天灾']
];

function getAnchor(kJ) {
    var J = (kJ || 0) * 1000;
    for (var i = 0; i < ANCHOR_TABLE.length; i++) {
        if (J <= ANCHOR_TABLE[i][0]) return ANCHOR_TABLE[i][1];
    }
    return '微弱感应';
}

var gb = fetchSnapshot();

if (!gb || !gb['主角']) {
    print('【渐变带系统】等待系统数据初始化同步...\n');
} else {
    var z = gb['主角'];
    var circuitMap = {};
    (gb['回路库'] || []).forEach(function(c) { circuitMap[c.id] = c; });

    // 0. 系统前缀与执行协议
    print('[SYSTEM NOTIFICATION: COMBAT & MAGIC ARBITRATION]\n');
    print('以下为底层物理引擎同步的【本回合实时状态机与战术调度准则】。\n');
    print('【正文AI强制执行协议】：\n');
    print('1. 动作执行约束：若本回合存在【已确认执行法术】，正文必须优先描写主角启动该术式，严禁擅自篡改成闪避、肉搏或消极避战；\n');
    print('2. 主观盲区法则：主角在实际出招前对法术是否会走火反噬完全未知。正文AI严禁因看到走火风险或反噬后果而代替主角产生畏缩、故意放弃施法；战况需要时主角必须坚决出招；\n');
    print('3. 叙事转化禁令：严禁在正文中复述“检定”、“掷骰”、“过载率”、“系统”、“点数”等元标签和数据括号，所有物理参数必须纯化为动作张力、肉体痛苦与环境破坏；\n');
    print('4. 权限边界：主角仅允许施展本面板【已装配可用回路】列出的术式，禁止凭空构筑未登记回路。\n');
    print('5. 形态锚点法则：每条回路的【形态锚点】是该术式外观的唯一合法依据。描写施法必须严格落在锚点给出的视觉相态、声学特征、空间形态与介质依赖之内，严禁自行发挥「绚丽光晕 / 魔法阵 / 神秘能量球 / 奇幻粒子」等奇幻辞藻；锚点为「—」的回路按该族物理机理保守描写，不得虚构具体形态。\n');
    print('----------------------------------------------------\n\n');

    // 1. 本回合玩家挂单及定点裁决
    var pend = gb['待扣单'] || [];
    print('#### 1. 本回合施法动作指令与即时裁决\n');

    if (pend.length) {
        pend.forEach(function(p, idx) {
            var cId = p.ref;
            var circuit = cId ? circuitMap[cId] : null;

            var risk = (circuit && circuit['过载风险'] !== undefined) ? circuit['过载风险'] : (p.risk || 0);
            var rateVal = 100;
            if (circuit && circuit['过载率'] !== undefined && circuit['过载率'] !== null) {
                rateVal = parseFloat(circuit['过载率']);
            }
            if (!isFinite(rateVal)) rateVal = 100;

            // 走火判定权归脚本：优先消费引擎本轮预掷的「本轮走火」（与结算结果严格一致）；
            // 仅当该字段缺失（旧档 / 尚未结算过）时才回退为本地掷骰。
            var roll = Math.floor(Math.random() * 100) + 1;
            var isOverloaded = (circuit && typeof circuit['本轮走火'] === 'boolean')
                ? circuit['本轮走火']
                : (roll <= risk);

            print('▶ **指令 ' + (idx + 1) + '**：' + (p['order'] || p['名称'] || '指定回路施放') + '\n');
            print('  - 系统物理仲裁：' + (isOverloaded ? '【走火失控：触发过载反噬】' : '【施法平稳：成功驾驭】') + '\n');

            if (!isOverloaded) {
                if (rateVal > 100) {
                    print('  - 生理表现：功率需求超额（' + rateVal + '%），但主角凭借意志强行压榨通径完成施法。重点描写额角青筋暴起、肌肉剧颤、经络滚烫发麻的极度负荷感，严禁描写回路烧穿或断裂。\n');
                } else {
                    print('  - 生理表现：魔素通导平稳顺畅，收放自如，正常产生体能与精神消耗，体感良好。\n');
                }
            } else {
                print('  - 伤害表现（正文必须在施法生效瞬间爆发此伤情）：\n');
                if (rateVal <= 100) {
                    print('    * 【轻度反噬】：回路末端震颤反冲，施法指尖/接触端红肿灼痛、神经麻木发凉，伴随局部轻度痉挛，短时间内该部位难以连续调动魔素。\n');
                } else if (rateVal <= 130) {
                    print('    * 【超频灼伤】：硬件超载叠加失控走火，体内回路产生溢出性烧蚀，皮下毛细血管破裂微渗血、皮肤泛起焦灼红痕，肢体剧烈抽搐剧痛。\n');
                } else {
                    print('    * 【毁灭性崩断】：严重超负荷引发体内魔素殉爆，经络回路大面积崩断烧蚀，脏腑受创，口鼻喷血，严重眩晕脱力濒临休克（身体状态滑落至重伤/过载透支）。\n');
                }
            }
            print('\n');
        });
    } else {
        print('- （当前回合玩家未手动挂单。主角根据当前战况意图自主抉择出招或战术交互，施法表现遵从下方回路参数与过载法则）\n\n');
    }

    // 2. 主角真实生理与精神负荷判定
    var eCur = z['能量kJ'] ? z['能量kJ']['当前'] : 0;
    var eMax = z['能量kJ'] ? z['能量kJ']['上限'] : 0;
    var mCur = z['精神点'] ? z['精神点']['当前'] : 0;
    var mMax = z['精神点'] ? z['精神点']['上限'] : 0;
    var pBurst = z['爆发线kW'] || 0;
    var pSustain = z['持续线kW'] || 0;

    // 精神负荷梯队判定
    var mRatio = mMax > 0 ? (mCur / mMax) : 1;
    var mStateDesc = '';
    var mNarrativeRule = '';

    if (mRatio >= 0.66) {
        mStateDesc = '【轻度负荷 / 清醒充沛】';
        mNarrativeRule = '神经感知锐利，魔素流向感知清晰；施法后仅有轻微发热与指尖微颤，注意力高度集中。';
    } else if (mRatio >= 0.33) {
        mStateDesc = '【中度负荷 / 神经紧绷】';
        mNarrativeRule = '手腕与手指出现不受控细微发抖，冷汗浸背，视野边缘出现毛刺感，太阳穴隐隐胀痛；施展自由回路时引导时间略微变长。';
    } else {
        mStateDesc = '【重度负荷 / 濒临断线】';
        mNarrativeRule = '耳鸣尖锐，眼前阵发性发黑，神经如烧红铁丝拉扯般剧痛，神志涣散；出现断线休克风险，极难集中注意力心算构筑自由回路（此时只能依赖肌肉记忆的固定回路保命）。';
    }

    print('#### 2. 主角机体状态与精神负荷判定\n');
    print('- **能量储备**：' + eCur + ' / ' + eMax + ' kJ\n');
    print('- **精神负荷**：' + mCur + ' / ' + mMax + ' 点 ➔ 状态分级：**' + mStateDesc + '**\n');
    print('  * **神志与生理表现指引**：' + mNarrativeRule + '\n');
    print('- **硬件通径线**：瞬时爆发 ' + pBurst + ' kW | 持续巡航 ' + pSustain + ' kW\n');
    print('- **机体创伤**：' + (z['身体状态'] || '正常') + ' | ' + (z['战斗中'] ? '【交战状态（精神锁死不自然恢复）】' : '【非交战状态】') + '\n');
    if (z['剧情时间'] && z['剧情时间']['label']) {
        print('- **剧情时间**：' + z['剧情时间']['label'] + '\n');
    }
    print('\n');

    // 3. 已装配可用回路（明确固定槽与自由槽机制）
    print('#### 3. 已装配可用回路（主角施法合法范围）\n');
    print('> **【槽位战术机制约束（严格执行）】**：\n');
    print('> - **固定槽（肌肉记忆）**：千锤百炼烧录入体的低阻抗回路。**出手极快极稳（本能瞬发）、精神消耗仅0~1点**。即使主角精神重度耗竭濒死，固定招依然能出手（残局底牌）；但参数彻底锁死不可微调，节拍恒定易被预判。战斗中固定槽整排上锁不可换装。\n');
    print('> - **自由槽（临时构筑）**：依靠神志临场搭建的动态回路。**形态、轨迹与威力可随心微调破局；但引导较慢、极易被打断、精神消耗极大**。若主角精神处于重度负荷或不足以支付账单，强行捏自由回路必将中途崩溃。战斗中自由槽回路可随时替换回库。\n');
    print('> - **形态锚点（外观唯一依据）**：每条回路列出的【形态锚点】直接取自法术AI 的物理审核结论，是该术式外观的**唯一合法形态依据**——视觉相态 / 声学特征 / 空间形态 / 介质依赖一律按锚点走，严禁自行发挥「绚丽光晕 / 魔法阵 / 神秘能量球」等奇幻辞藻；锚点为「—」时（旧档或早期预设数据）按该族机理保守描写，不得虚构具体形态。\n\n');

    var count = 0;
    function printCircuit(id, slotType) {
        if (!id) return;
        var c = circuitMap[id];
        if (!c) return;

        var audit = c['审核状态'] || '已通过';
        if (audit === '待送审') return;   // 枚举只有 免审|待送审|已通过（旧写的「已驳回」状态并不存在）

        count++;
        var bill = c['基线账单'] || {};
        var isFixed = (c['type'] === 'fixed');
        var rateNum = Number(c['过载率']);
        var overRate = isFinite(rateNum) ? (Math.round(rateNum * 10) / 10) + '%' : '100%';
        var riskVal = (c['过载风险'] !== undefined) ? c['过载风险'] : 0;
        var mCost = bill['精神'] !== undefined ? bill['精神'] : (isFixed ? 0 : 4);
        var 形态锚点 = c['物理相态与表征'];
        var 本轮定数 = (typeof c['本轮走火'] === 'boolean')
            ? (c['本轮走火'] ? '【已判定：将走火失控】' : '【已判定：可稳定驾驭】')
            : '—';

        print(count + '. **' + c['名称'] + '** 【' + slotType + ' · ' + (isFixed ? '固化' : '自由') + '】（' + c['族'] + '·' + c['分支'] + '）：\n');
        print('   - 战术特性：' + (isFixed ? '本能瞬发，极省神志（精神耗 ' + mCost + '）' : '需凝神引导微调，高精神负荷（精神耗 ' + mCost + '）') + ' | 破坏力：【' + getAnchor(bill['输出kJ']) + '】\n');
        print('   - 基线效果：' + (bill['一句话效果'] || '标准输出') + '\n');
        print('   - 形态锚点：' + (形态锚点 ? 形态锚点 : '—') + '\n');
        print('   - 硬件过载率：' + overRate + ' | 走火失控风险：' + riskVal + ' / 100 | 本轮走火定数：' + 本轮定数 + '\n');
    }

    (gb['槽位']['固定槽'] || []).forEach(function(id) { printCircuit(id, '固定槽'); });
    (gb['槽位']['自由槽'] || []).forEach(function(id) { printCircuit(id, '自由槽'); });

    if (!count) print('（当前槽位未装配任何可用回路，主角无法释放法术）\n');
    print('\n');

    // 4. 当前物理环境与介质
    print('#### 4. 现场物理环境与介质约束\n');
    if (gb['场景']) {
        var sc = gb['场景'];
        print('- **风力条件**：' + (sc['风力档'] !== undefined ? sc['风力档'] + ' 档' : '微风') + '（高风力增幅气流媒介波，无风全靠自力）\n');
        print('- **水体存在**：' + (sc['水体在场'] ? '附近存在可用水体（允许引导水流媒介波）' : '无开放水体（严禁凭空造水借水）') + '\n');
        print('- **可塑无机物**：' + (sc['可塑无机物kJ'] ? '约 ' + getAnchor(sc['可塑无机物kJ']) + ' 强度材料' : '匮乏') + '（结构系塑形硬化必须就地取材）\n');
    } else {
        print('- （常规干燥无风室内环境）\n');
    }
    print('\n');

    // 5. 自主施法时的两段式执行法则
    print('#### 5. 自主施法与过载两段式执行法则\n');
    print('- **判定顺序**：\n');
    print('  1. **第一步（判走火）**：以该回路的【本轮走火定数】为准（脚本已在上一轮结算时按【走火失控风险 (0-100)】预掷写入，正文AI 严禁自行改判或另掷骰）。若未失控，无论过载率多高，仅表现为压榨肉体的紧绷与脱力负荷，不进入过载状态、不写身体灼伤毁损；\n');
    print('  2. **第二步（判创伤）**：唯有在走火失控时，才根据【硬件过载率】呈现反噬创伤（≤100% 为指尖红肿轻度麻木；101%~130% 为毛细血管破裂与溢出灼伤；>130% 为回路崩断吐血休克）；\n');
    print('- **破坏力标尺**：法术命中破坏力严格对齐【实效破坏力】，禁止夸大词汇；数值结算完全归后台处理。\n');
}
